  created_by                   varchar(64),
  agent_id                     uuid NOT NULL,
  user_subject                 varchar(64),
  action                       varchar(64) NOT NULL,
  object_type                  varchar(40),
  object_id                    uuid,
  outcome                      varchar(40) NOT NULL CHECK (outcome IN ('SUCCEEDED', 'DENIED', 'STEP_UP_REQUIRED', 'SIGNATURE_INVALID', 'RATE_LIMITED', 'FAILED')),
  error_code                   varchar(64),
  result_id                    uuid,
  agent_device_id              uuid,
  auth_method                  varchar(40) CHECK (auth_method IN ('RECENT_LOGIN', 'DEVICE_PROOF', 'NONE')),
  auth_age_seconds             integer,
  acr                          varchar(64),
  ip_address                   inet,
  user_agent                   varchar(255)
);
